scenarios.example_code:
import { installConnector } from '@projexlight/connector-salesforce';
const { install_id } = await installConnector({
  tenant_id, sf_org_id, auth_code,
  redirect_uri: 'https://app.projexcloud.com/connect/salesforce/callback',
});

import { registerBinding } from '@projexlight/connector-salesforce';
await registerBinding({
  install_id, projex_entity: 'sdk-lead-scoring.lead_score',
  sf_object: 'Lead', sf_field_map: { score: 'Lead_Score__c' },
  direction: 'push', cadence_min: 15,
});

import { handleWebhook } from '@projexlight/connector-salesforce';
await handleWebhook({
  tenant_id, signature, body, event_type: 'OpportunityClosedWon',
});

subscribeEvents('secrets.secret.rotated.v1', async (e) => {
  const installs = await findInstallsUsingSecret({ secret_ref: e.payload.ref });
  for (const i of installs) await reTestSfConnection({ install_id: i.id });
});
